import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface DailyDataPoint {
  label: string;
  value: number;
}

interface TopChart {
  chartId: string | null;
  chartName: string;
  views: number;
  rank: number;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const url = new URL(request.url);
  const fromParam = url.searchParams.get("from");
  const toParam = url.searchParams.get("to");
  const presetParam = url.searchParams.get("preset") ?? "30d";

  // Resolve date range
  const now = new Date();
  let fromDate: Date;
  let toDate: Date = new Date(now);
  toDate.setHours(23, 59, 59, 999);

  if (fromParam && toParam) {
    fromDate = new Date(fromParam);
    fromDate.setHours(0, 0, 0, 0);
    const parsedTo = new Date(toParam);
    parsedTo.setHours(23, 59, 59, 999);
    toDate = parsedTo;
  } else {
    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
    fromDate.setHours(0, 0, 0, 0);
  }

  const dateFilter = { gte: fromDate, lte: toDate };

  const subscription = await db.subscription.findUnique({ where: { shop } });
  const plan = getPlan(subscription?.planId ?? "free");
  const canViewAnalytics = hasFeature(plan.id, "analytics");

  if (!canViewAnalytics) {
    return {
      plan,
      canViewAnalytics: false as const,
      stats: null,
      topChartsWithNames: [] as TopChart[],
      dailyTrend: [] as DailyDataPoint[],
      preset: presetParam,
      fromDate: fromDate.toISOString().split("T")[0],
      toDate: toDate.toISOString().split("T")[0],
    };
  }

  const [
    totalViews,
    totalClicks,
    totalRecommendations,
    totalConverts,
    topCharts,
    rawEvents,
  ] = await Promise.all([
    db.analyticsEvent.count({ where: { shop, eventType: "view", createdAt: dateFilter } }),
    db.analyticsEvent.count({ where: { shop, eventType: "click", createdAt: dateFilter } }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend", createdAt: dateFilter } }),
    db.analyticsEvent.count({ where: { shop, eventType: "convert", createdAt: dateFilter } }),
    db.analyticsEvent.groupBy({
      by: ["sizeChartId"],
      where: { shop, eventType: "view", sizeChartId: { not: null }, createdAt: dateFilter },
      _count: { id: true },
      orderBy: { _count: { id: "desc" } },
      take: 5,
    }),
    db.analyticsEvent.findMany({
      where: { shop, eventType: "view", createdAt: dateFilter },
      select: { createdAt: true },
      orderBy: { createdAt: "asc" },
    }),
  ]);

  // Build daily trend bucketed by day
  const dayBuckets: Record<string, number> = {};
  const diffMs = toDate.getTime() - fromDate.getTime();
  const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
  for (let i = 0; i < Math.min(diffDays, 90); i++) {
    const d = new Date(fromDate.getTime() + i * 24 * 60 * 60 * 1000);
    const key = d.toISOString().split("T")[0];
    dayBuckets[key] = 0;
  }
  for (const ev of rawEvents) {
    const key = ev.createdAt.toISOString().split("T")[0];
    if (key in dayBuckets) dayBuckets[key]++;
  }

  // Condense to max 30 bars for readability
  const bucketEntries = Object.entries(dayBuckets);
  const maxBars = 30;
  let dailyTrend: DailyDataPoint[];
  if (bucketEntries.length <= maxBars) {
    dailyTrend = bucketEntries.map(([date, value]) => ({
      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
      value,
    }));
  } else {
    // Group into weekly buckets
    const weekBuckets: Record<string, number> = {};
    for (const [date, count] of bucketEntries) {
      const d = new Date(date + "T12:00:00Z");
      const weekStart = new Date(d);
      weekStart.setDate(d.getDate() - d.getDay());
      const wk = weekStart.toISOString().split("T")[0];
      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + count;
    }
    dailyTrend = Object.entries(weekBuckets).map(([date, value]) => ({
      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
      value,
    }));
  }

  // Resolve chart names
  const chartIds = topCharts.map((tc) => tc.sizeChartId).filter((id): id is string => id !== null);
  const charts = chartIds.length > 0
    ? await db.sizeChart.findMany({ where: { id: { in: chartIds }, shop }, select: { id: true, name: true } })
    : [];

  const topChartsWithNames: TopChart[] = topCharts.map((tc, idx) => ({
    chartId: tc.sizeChartId,
    chartName: charts.find((c) => c.id === tc.sizeChartId)?.name ?? "Unknown",
    views: tc._count.id,
    rank: idx + 1,
  }));

  // Funnel rates
  const clickRate = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(1) : "0";
  const recommendRate = totalClicks > 0 ? ((totalRecommendations / totalClicks) * 100).toFixed(1) : "0";
  const convertRate = totalRecommendations > 0 ? ((totalConverts / totalRecommendations) * 100).toFixed(1) : "0";
  const overallConvertRate = totalViews > 0 ? ((totalConverts / totalViews) * 100).toFixed(1) : "0";

  return {
    plan,
    canViewAnalytics: true as const,
    stats: {
      totalViews,
      totalClicks,
      totalRecommendations,
      totalConverts,
      clickRate,
      recommendRate,
      convertRate,
      overallConvertRate,
    },
    topChartsWithNames,
    dailyTrend,
    preset: presetParam,
    fromDate: fromDate.toISOString().split("T")[0],
    toDate: toDate.toISOString().split("T")[0],
  };
};

// ---------------------------------------------------------------------------
// BarChart sub-component (custom visualization — minimal inline styles)
// ---------------------------------------------------------------------------

function BarChart({ data }: { data: DailyDataPoint[] }) {
  const max = Math.max(...data.map((d) => d.value), 1);
  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: "2px", height: "120px" }}>
      {data.map((d, i) => (
        <div
          key={i}
          style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}
          title={`${d.label}: ${d.value} views`}
        >
          <div
            style={{
              width: "100%",
              background: "#005bd3",
              borderRadius: "2px 2px 0 0",
              height: `${(d.value / max) * 100}%`,
              minHeight: d.value > 0 ? "2px" : "0",
            }}
          />
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// FunnelBar sub-component (inline style — custom visualization)
// ---------------------------------------------------------------------------

function FunnelBar({ rate, color }: { rate: number; color: string }) {
  return (
    <div style={{ height: "6px", background: "#e4e5e7", borderRadius: "3px", overflow: "hidden", marginTop: "4px" }}>
      <div
        style={{
          height: "100%",
          background: color,
          borderRadius: "3px",
          width: `${Math.min(100, rate)}%`,
          transition: "width 0.3s ease",
        }}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// RankBadge sub-component
// ---------------------------------------------------------------------------

function RankBadge({ rank }: { rank: number }) {
  const colors: Record<number, string> = { 1: "#FFD700", 2: "#C0C0C0", 3: "#CD7F32" };
  return (
    <div
      style={{
        width: "28px",
        height: "28px",
        borderRadius: "50%",
        background: colors[rank] ?? "#e4e5e7",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "12px",
        fontWeight: 700,
        flexShrink: 0,
        color: rank <= 3 ? "#333" : "#666",
      }}
    >
      {rank}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const PRESET_OPTIONS = [
  { label: "7 days", value: "7d" },
  { label: "30 days", value: "30d" },
  { label: "90 days", value: "90d" },
];

export default function Analytics() {
  const loaderData = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof loader>();
  const shopify = useAppBridge();

  const [activePreset, setActivePreset] = useState(loaderData.preset ?? "30d");

  // Use fetcher data when available (after date range change), else loader data
  const data = fetcher.data ?? loaderData;
  const isLoading = fetcher.state !== "idle";

  function handlePreset(preset: string) {
    setActivePreset(preset);
    fetcher.load(`/app/analytics?preset=${preset}`);
  }

  // Gate check — use loaderData since data might be the fetcher result
  if (!data.canViewAnalytics) {
    return (
      <s-page heading="Analytics">
        <s-section>
          <s-banner tone="warning" heading="Analytics is a Growth plan feature">
            <s-stack direction="block" gap="base">
              <s-text>
                Track how customers interact with your size charts. See chart views, click-through rates,
                AI recommendation usage, and conversion impact — all in one dashboard.
              </s-text>
              <s-stack direction="inline" gap="base">
                <s-button variant="primary" href="/app/pricing">Upgrade to Growth — $9.99/mo</s-button>
                <s-button href="/app/pricing">Compare all plans</s-button>
              </s-stack>
            </s-stack>
          </s-banner>
        </s-section>

        <s-section heading="What you'll unlock">
          <s-stack direction="inline" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>Chart Views</s-heading>
                <s-text color="subdued">See exactly how many customers open your size charts by product and date range.</s-text>
              </s-stack>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>Conversion Funnel</s-heading>
                <s-text color="subdued">Measure the path from chart view to AI recommendation to add-to-cart.</s-text>
              </s-stack>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>Top Charts</s-heading>
                <s-text color="subdued">Identify which size charts drive the most customer engagement.</s-text>
              </s-stack>
            </s-box>
          </s-stack>
        </s-section>

        <s-section slot="aside" heading="Your plan">
          <s-stack direction="block" gap="base">
            <s-badge tone="neutral">{data.plan.name}</s-badge>
            <s-text color="subdued">Analytics unlocks on Growth ($9.99/mo) and above.</s-text>
            <s-button href="/app/pricing" variant="primary">View pricing</s-button>
          </s-stack>
        </s-section>
      </s-page>
    );
  }

  const { stats, topChartsWithNames, dailyTrend } = data;
  const hasData = stats !== null && stats.totalViews > 0;
  const canViewReturnAttribution = hasFeature(data.plan.id, "returnAttribution");

  return (
    <s-page heading="Analytics">
      {/* Primary action — date range controls */}
      <s-button-group slot="primary-action">
        {PRESET_OPTIONS.map((opt) => (
          <s-button
            key={opt.value}
            variant={activePreset === opt.value ? "primary" : undefined}
            onClick={() => handlePreset(opt.value)}
            disabled={isLoading}
          >
            {opt.label}
          </s-button>
        ))}
      </s-button-group>

      {/* ================================================================ */}
      {/* UPGRADE BANNER — return attribution (Pro feature)                 */}
      {/* ================================================================ */}
      {!canViewReturnAttribution && hasData && (
        <s-section>
          <s-banner tone="info" heading="Unlock Return Attribution — Pro plan">
            <s-stack direction="inline" gap="base">
              <s-text>
                Connect size chart interactions directly to return rates. See exactly how much revenue your size charts protect.
              </s-text>
              <s-button href="/app/pricing">Upgrade to Pro</s-button>
            </s-stack>
          </s-banner>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* EMPTY STATE                                                        */}
      {/* ================================================================ */}
      {!hasData && (
        <s-section>
          <s-box padding="large-200" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              <s-heading>No data yet for this period</s-heading>
              <s-text color="subdued">
                Analytics data appears as soon as customers start viewing your size charts on your storefront.
                Make sure your widget is enabled and a size chart is assigned to at least one product.
              </s-text>
              <s-stack direction="inline" gap="base">
                <s-button variant="primary" href="/app/size-charts">Manage size charts</s-button>
                <s-button href="/app/widget">Check widget settings</s-button>
              </s-stack>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* STATS OVERVIEW CARDS                                              */}
      {/* ================================================================ */}
      {stats !== null && (
        <s-section heading="Overview">
          <s-stack direction="inline" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>{isLoading ? "—" : stats.totalViews.toLocaleString()}</s-heading>
                <s-text>Total Views</s-text>
                <s-text color="subdued">Size chart opens</s-text>
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>{isLoading ? "—" : stats.totalClicks.toLocaleString()}</s-heading>
                <s-text>Interactions</s-text>
                <s-text color="subdued">Clicks within chart</s-text>
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>{isLoading ? "—" : stats.totalRecommendations.toLocaleString()}</s-heading>
                <s-text>AI Recommendations</s-text>
                <s-text color="subdued">Sizes suggested by AI</s-text>
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-heading>{isLoading ? "—" : stats.totalConverts.toLocaleString()}</s-heading>
                <s-text>Conversions</s-text>
                <s-text color="subdued">Add-to-cart after chart</s-text>
              </s-stack>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* DAILY TREND CHART                                                  */}
      {/* ================================================================ */}
      {hasData && dailyTrend.length > 0 && (
        <s-section heading="Daily Views Trend">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-text color="subdued">Chart views per day across the selected period</s-text>
              <BarChart data={dailyTrend} />
              <s-stack direction="inline" gap="base">
                <s-text color="subdued">{dailyTrend[0]?.label ?? ""}</s-text>
                <s-text color="subdued">{dailyTrend[dailyTrend.length - 1]?.label ?? ""}</s-text>
              </s-stack>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* CONVERSION FUNNEL                                                  */}
      {/* ================================================================ */}
      {hasData && stats !== null && (
        <s-section heading="Conversion Funnel">
          <s-stack direction="block" gap="small-200">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-stack direction="inline" gap="base">
                  <s-text>Views → Interactions</s-text>
                  <s-badge tone={parseFloat(stats.clickRate) >= 20 ? "success" : "neutral"}>
                    {stats.clickRate}%
                  </s-badge>
                </s-stack>
                <s-text color="subdued">
                  {stats.totalClicks.toLocaleString()} of {stats.totalViews.toLocaleString()} chart viewers clicked inside
                </s-text>
                <FunnelBar rate={parseFloat(stats.clickRate)} color="#005bd3" />
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-stack direction="inline" gap="base">
                  <s-text>Interactions → AI Recommendations</s-text>
                  <s-badge tone={parseFloat(stats.recommendRate) >= 30 ? "success" : "neutral"}>
                    {stats.recommendRate}%
                  </s-badge>
                </s-stack>
                <s-text color="subdued">
                  {stats.totalRecommendations.toLocaleString()} customers used the AI size recommender
                </s-text>
                <FunnelBar rate={parseFloat(stats.recommendRate)} color="#2c7be5" />
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-stack direction="inline" gap="base">
                  <s-text>Recommendations → Conversions</s-text>
                  <s-badge tone={parseFloat(stats.convertRate) >= 40 ? "success" : "neutral"}>
                    {stats.convertRate}%
                  </s-badge>
                </s-stack>
                <s-text color="subdued">
                  {stats.totalConverts.toLocaleString()} customers added to cart after receiving a recommendation
                </s-text>
                <FunnelBar rate={parseFloat(stats.convertRate)} color="#1a73e8" />
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-stack direction="inline" gap="base">
                  <s-text>Overall: Views → Conversions</s-text>
                  <s-badge tone={parseFloat(stats.overallConvertRate) >= 5 ? "success" : "neutral"}>
                    {stats.overallConvertRate}%
                  </s-badge>
                </s-stack>
                <s-text color="subdued">
                  End-to-end conversion rate — customers who viewed a chart and then added to cart
                </s-text>
                <FunnelBar rate={parseFloat(stats.overallConvertRate) * 5} color="#16a34a" />
              </s-stack>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* TOP CHARTS BY VIEWS                                               */}
      {/* ================================================================ */}
      <s-section heading="Top Size Charts">
        {topChartsWithNames.length === 0 ? (
          <s-text color="subdued">
            No chart views in this period. Data appears once customers start viewing your size charts.
          </s-text>
        ) : (
          <s-stack direction="block" gap="small-200">
            {topChartsWithNames.map((chart) => (
              <s-box key={chart.chartId ?? chart.rank} padding="base" borderWidth="base" borderRadius="base">
                <s-stack direction="inline" gap="base">
                  <RankBadge rank={chart.rank} />
                  <s-stack direction="block" gap="small-100">
                    <s-link href={chart.chartId ? `/app/size-charts/${chart.chartId}` : "/app/size-charts"}>
                      {chart.chartName}
                    </s-link>
                    <s-text color="subdued">{chart.views.toLocaleString()} view{chart.views !== 1 ? "s" : ""}</s-text>
                  </s-stack>
                </s-stack>
              </s-box>
            ))}
          </s-stack>
        )}
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Insights                                                   */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Insights">
        <s-stack direction="block" gap="base">
          {hasData && stats !== null && parseFloat(stats.clickRate) < 10 && (
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-text>Low click rate detected</s-text>
                <s-text color="subdued">
                  Your chart view-to-click rate is below 10%. Try moving your size chart widget higher up on the product page.
                </s-text>
              </s-stack>
            </s-box>
          )}
          {hasData && stats !== null && parseFloat(stats.recommendRate) < 20 && (
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="small-200">
                <s-text>AI recommender underused</s-text>
                <s-text color="subdued">
                  Fewer than 20% of chart interactions use the AI recommender. Enable it prominently in your widget settings.
                </s-text>
              </s-stack>
            </s-box>
          )}
          <s-unordered-list>
            <s-list-item>Charts with high views but low clicks may need better positioning</s-list-item>
            <s-list-item>High AI recommendation usage correlates with lower return rates</s-list-item>
            <s-list-item>Track your overall conversion rate to measure size chart ROI</s-list-item>
            <s-list-item>Mobile customers convert 30% better with an inline widget</s-list-item>
          </s-unordered-list>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Plan & Upsell                                             */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Your plan">
        <s-stack direction="block" gap="base">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone={data.plan.id === "free" ? "neutral" : "success"}>{data.plan.name}</s-badge>
            <s-text color="subdued">
              {data.plan.price === 0 ? "Free" : `$${data.plan.price}/mo`}
            </s-text>
          </s-stack>

          {!canViewReturnAttribution && (
            <s-stack direction="block" gap="small-200">
              <s-divider />
              <s-text>Return Attribution</s-text>
              <s-text color="subdued">
                Available on Pro plan. See exactly which charts reduce returns and calculate revenue saved.
              </s-text>
              <s-button href="/app/pricing">Upgrade to Pro</s-button>
            </s-stack>
          )}

          {canViewReturnAttribution && (
            <s-banner tone="success" heading="Return Attribution active">
              <s-text color="subdued">Your Pro plan includes full return attribution analytics.</s-text>
            </s-banner>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Date range summary                                         */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Date range">
        <s-stack direction="block" gap="small-200">
          <s-text color="subdued">
            Showing data from {new Date(data.fromDate + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })} to {new Date(data.toDate + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
          </s-text>
          <s-divider />
          {PRESET_OPTIONS.map((opt) => (
            <s-button
              key={opt.value}
              variant={activePreset === opt.value ? "primary" : undefined}
              onClick={() => handlePreset(opt.value)}
              disabled={isLoading}
            >
              Last {opt.label}
            </s-button>
          ))}
        </s-stack>
      </s-section>
    </s-page>
  );
}

import { useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { useEffect } from "react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { PLANS, getPlan } from "../lib/plans";

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const subscription = await db.subscription.findUnique({ where: { shop } });
  const currentPlan = getPlan(subscription?.planId ?? "free");

  return {
    currentPlan,
    billingInterval: subscription?.billingInterval ?? "monthly",
    plans: PLANS,
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "subscribe": {
        const planId = formData.get("planId") as string;
        const interval = (formData.get("interval") as string) || "monthly";
        const plan = getPlan(planId);

        if (plan.price === 0) {
          await db.subscription.upsert({
            where: { shop },
            update: { planId: "free", status: "active", billingInterval: "monthly" },
            create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
          });
          return { ok: true, message: "Switched to Free plan" };
        }

        // In production this calls the Shopify billing API
        // For now, simulate by updating local DB to demonstrate flow
        await db.subscription.upsert({
          where: { shop },
          update: { planId, billingInterval: interval, status: "active" },
          create: { shop, planId, billingInterval: interval, status: "active" },
        });

        return { ok: true, message: `Subscribed to ${plan.name} plan` };
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    return { error: message };
  }
};

// ---------------------------------------------------------------------------
// Checkmark sub-component (custom visual — no Polaris equivalent)
// ---------------------------------------------------------------------------

function CheckIcon({ included }: { included: boolean }) {
  return (
    <div
      style={{
        width: "18px",
        height: "18px",
        borderRadius: "50%",
        background: included ? "#1a73e8" : "#e4e5e7",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "10px",
        color: included ? "#fff" : "#999",
        flexShrink: 0,
      }}
    >
      {included ? "✓" : "—"}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const PLAN_ORDER = ["free", "starter", "growth", "pro"];

// Feature rows for comparison table
const FEATURE_ROWS: { label: string; key: keyof (typeof PLANS)[0]["limits"] }[] = [
  { label: "Published size charts", key: "maxCharts" },
  { label: "CSV import / export", key: "csvImport" },
  { label: "Auto-assignment rules", key: "autoAssign" },
  { label: "Translate & Adapt (native i18n)", key: "translateAdapt" },
  { label: "Analytics dashboard", key: "analytics" },
  { label: "AI size recommender (basic)", key: "aiRecommender" },
  { label: "Advanced ML recommender", key: "advancedAi" },
  { label: "Return attribution analytics", key: "returnAttribution" },
  { label: "Priority support (<2hr)", key: "prioritySupport" },
  { label: "Multi-store sync", key: "multiStore" },
  { label: "Dedicated sizing page", key: "dedicatedSizingPage" },
  { label: "Image support in charts", key: "imageInCharts" },
];

export default function Pricing() {
  const { currentPlan, billingInterval: initialInterval, plans } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [interval, setInterval] = useState<"monthly" | "annual">(
    initialInterval === "annual" ? "annual" : "monthly",
  );

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (fetcher.data?.ok) {
      shopify.toast.show(fetcher.data.message ?? "Plan updated");
    } else if (fetcher.data?.error) {
      shopify.toast.show(fetcher.data.error, { isError: true });
    }
  }, [fetcher.data, shopify]);

  function handleSubscribe(planId: string) {
    fetcher.submit(
      { intent: "subscribe", planId, interval },
      { method: "post" },
    );
  }

  function getPriceDisplay(plan: (typeof PLANS)[0]): string {
    if (plan.price === 0) return "Free";
    if (interval === "annual") {
      const monthly = (plan.annualPrice / 12).toFixed(2);
      return `$${monthly}/mo`;
    }
    return `$${plan.price}/mo`;
  }

  function getAnnualNote(plan: (typeof PLANS)[0]): string | null {
    if (plan.price === 0) return null;
    if (interval === "annual") return `Billed $${plan.annualPrice}/year`;
    return `Or $${(plan.annualPrice / 12).toFixed(2)}/mo billed annually (save 20%)`;
  }

  const orderedPlans = PLAN_ORDER.map((id) => plans.find((p) => p.id === id)).filter(
    (p): p is (typeof PLANS)[0] => p !== undefined,
  );

  return (
    <s-page heading="Plans & Pricing">
      {/* ================================================================ */}
      {/* HEADER                                                            */}
      {/* ================================================================ */}
      <s-section>
        <s-stack direction="block" gap="base">
          <s-heading>Simple, transparent pricing. No per-order fees. No hidden charges. Ever.</s-heading>
          <s-text color="subdued">
            Reduce size-related returns by up to 40%. Start free — upgrade when you're ready.
          </s-text>

          <s-stack direction="inline" gap="small-200">
            <s-text>Monthly</s-text>
            <s-switch
              checked={interval === "annual"}
              onChange={(e: Event) => {
                const checked = (e.target as HTMLInputElement).checked;
                setInterval(checked ? "annual" : "monthly");
              }}
            />
            <s-text>Annual</s-text>
            <s-badge tone="success">Save 20%</s-badge>
          </s-stack>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* PLAN CARDS                                                        */}
      {/* ================================================================ */}
      <s-section>
        <s-stack direction="inline" gap="base">
          {orderedPlans.map((plan) => {
            const isCurrent = plan.id === currentPlan.id;
            const planIndex = PLAN_ORDER.indexOf(plan.id);
            const currentIndex = PLAN_ORDER.indexOf(currentPlan.id);
            const isUpgrade = planIndex > currentIndex;
            const isDowngrade = planIndex < currentIndex;
            const isGrowth = plan.id === "growth";
            const isPro = plan.id === "pro";
            const annualNote = getAnnualNote(plan);

            return (
              <s-box
                key={plan.id}
                padding="base"
                borderWidth={isGrowth ? "large" : "base"}
                borderRadius="base"
              >
                <s-stack direction="block" gap="base">
                  {/* Plan badges */}
                  <s-stack direction="inline" gap="small-200">
                    {isCurrent && <s-badge tone="success">Current Plan</s-badge>}
                    {isGrowth && !isCurrent && <s-badge tone="info">Most Popular</s-badge>}
                    {isPro && interval === "annual" && !isCurrent && (
                      <s-badge tone="success">Best Value</s-badge>
                    )}
                  </s-stack>

                  {/* Plan name & price */}
                  <s-stack direction="block" gap="small-100">
                    <s-heading>{plan.name}</s-heading>
                    <s-heading>{getPriceDisplay(plan)}</s-heading>
                    {annualNote && <s-text color="subdued">{annualNote}</s-text>}
                  </s-stack>

                  <s-divider />

                  {/* Feature list */}
                  <s-stack direction="block" gap="small-200">
                    {plan.features.map((feature, i) => (
                      <s-stack key={i} direction="inline" gap="small-200">
                        <CheckIcon included={true} />
                        <s-text>{feature}</s-text>
                      </s-stack>
                    ))}
                  </s-stack>

                  {/* CTA button */}
                  {isCurrent ? (
                    <s-button disabled>Current Plan</s-button>
                  ) : isUpgrade ? (
                    <s-button
                      variant="primary"
                      onClick={() => handleSubscribe(plan.id)}
                      disabled={isLoading}
                    >
                      Upgrade to {plan.name}
                    </s-button>
                  ) : isDowngrade ? (
                    <s-button
                      variant="tertiary"
                      onClick={() => handleSubscribe(plan.id)}
                      disabled={isLoading}
                    >
                      Downgrade to {plan.name}
                    </s-button>
                  ) : null}

                  {plan.price === 0 && !isCurrent && (
                    <s-button
                      variant="tertiary"
                      onClick={() => handleSubscribe(plan.id)}
                      disabled={isLoading}
                    >
                      Switch to Free
                    </s-button>
                  )}

                  {/* Limit note for free plan */}
                  {plan.id === "free" && (
                    <s-text color="subdued">
                      Up to {plan.limits.maxCharts} published charts
                    </s-text>
                  )}
                  {plan.id !== "free" && (
                    <s-text color="subdued">Unlimited size charts</s-text>
                  )}
                </s-stack>
              </s-box>
            );
          })}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* GUARANTEE BANNER                                                  */}
      {/* ================================================================ */}
      <s-section>
        <s-banner tone="success" heading="30-day money-back guarantee">
          <s-text>
            Not happy in the first 30 days? We'll refund you — no questions asked.
            Cancel anytime directly from your Shopify billing settings.
          </s-text>
        </s-banner>
      </s-section>

      {/* ================================================================ */}
      {/* WHY MERCHANTS SWITCH                                              */}
      {/* ================================================================ */}
      <s-section heading="Why Merchants Switch to Us">
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>No Per-Order Fees</s-heading>
              <s-text color="subdued">
                Competitors like Kiwi Sizing charge per order processed — costs balloon as your store grows.
                We use simple flat monthly pricing. Your bill stays predictable no matter how many orders you get.
              </s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>Mobile-First by Default</s-heading>
              <s-text color="subdued">
                iOS Safari bugs are the #1 complaint in competitor reviews. Our widget is built mobile-first from the ground up —
                pixel-perfect on every device, tested across all major browsers.
              </s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>Set Up in Under 5 Minutes</s-heading>
              <s-text color="subdued">
                Auto-detect product types, suggest matching templates, and auto-assign charts — all in one flow.
                Most merchants publish their first chart in under 3 minutes.
              </s-text>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* FEATURE COMPARISON TABLE                                          */}
      {/* ================================================================ */}
      <s-section heading="Full Feature Comparison">
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="small-200">
            {/* Header row */}
            <s-stack direction="inline" gap="base">
              <s-text color="subdued" style={{ flex: 2 }}>Feature</s-text>
              {orderedPlans.map((plan) => (
                <s-stack key={plan.id} direction="block" gap="small-100" style={{ flex: 1, textAlign: "center" }}>
                  <s-text>{plan.name}</s-text>
                  <s-text color="subdued">{getPriceDisplay(plan)}</s-text>
                </s-stack>
              ))}
            </s-stack>

            <s-divider />

            {/* Feature rows */}
            {FEATURE_ROWS.map((row) => (
              <s-stack key={row.key} direction="inline" gap="base">
                <s-text style={{ flex: 2 }}>{row.label}</s-text>
                {orderedPlans.map((plan) => {
                  const val = plan.limits[row.key];
                  let display: boolean;
                  let overrideText: string | null = null;
                  if (row.key === "maxCharts") {
                    display = true;
                    overrideText = val === -1 ? "Unlimited" : String(val);
                  } else {
                    display = val as boolean;
                  }
                  return (
                    <div key={plan.id} style={{ flex: 1, display: "flex", justifyContent: "center" }}>
                      {overrideText ? (
                        <s-text>{overrideText}</s-text>
                      ) : (
                        <CheckIcon included={display} />
                      )}
                    </div>
                  );
                })}
              </s-stack>
            ))}
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Current Plan Summary                                      */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Your current plan">
        <s-stack direction="block" gap="base">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone={currentPlan.id === "free" ? "neutral" : "success"}>
              {currentPlan.name}
            </s-badge>
            <s-text color="subdued">
              {currentPlan.price === 0 ? "Free" : `$${currentPlan.price}/mo`}
            </s-text>
          </s-stack>

          <s-unordered-list>
            {currentPlan.features.map((f, i) => (
              <s-list-item key={i}>{f}</s-list-item>
            ))}
          </s-unordered-list>

          {currentPlan.id === "free" && (
            <s-button href="#" variant="primary" onClick={() => handleSubscribe("growth")}>
              Upgrade to Growth
            </s-button>
          )}

          <s-divider />
          <s-text color="subdued">Questions about billing?</s-text>
          <s-link href="mailto:support@sizechart.app">Contact support</s-link>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — FAQ                                                       */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="FAQ">
        <s-stack direction="block" gap="base">
          <s-stack direction="block" gap="small-200">
            <s-text>Can I switch plans anytime?</s-text>
            <s-text color="subdued">
              Yes. Upgrade instantly — your new features activate immediately.
              Downgrades take effect at the end of your current billing period.
            </s-text>
          </s-stack>

          <s-divider />

          <s-stack direction="block" gap="small-200">
            <s-text>What happens to my charts if I downgrade?</s-text>
            <s-text color="subdued">
              Charts are never deleted. On Free, only your 3 most recently updated charts remain published.
              The rest are paused and can be re-published when you upgrade again.
            </s-text>
          </s-stack>

          <s-divider />

          <s-stack direction="block" gap="small-200">
            <s-text>Is there a free trial?</s-text>
            <s-text color="subdued">
              The Free plan is permanent — it's not a time-limited trial.
              Upgrade whenever you're ready for more features.
            </s-text>
          </s-stack>

          <s-divider />

          <s-stack direction="block" gap="small-200">
            <s-text>Are there per-order or per-recommendation fees?</s-text>
            <s-text color="subdued">
              Never. Our pricing is always flat monthly (or annual). No hidden charges, no per-order fees,
              no matter how large your store grows.
            </s-text>
          </s-stack>

          <s-divider />

          <s-stack direction="block" gap="small-200">
            <s-text>Does the annual plan auto-renew?</s-text>
            <s-text color="subdued">
              Yes, annual plans renew automatically. You can cancel anytime from Shopify Admin
              under Settings → Billing. No cancellation fees.
            </s-text>
          </s-stack>
        </s-stack>
      </s-section>
    </s-page>
  );
}

